#include <iostream>
#include <sstream>
#include <string>
#include <cctype>

void analyzeText(std::istream& in, int& lines, int& letters, int& digits, std::string& longestWord) {
    lines = 0;
    letters = 0;
    digits = 0;
    longestWord.clear();

    std::string line;
    while (std::getline(in, line)) {
        lines++;
        std::stringstream ss(line);
        std::string word;
        while (ss >> word) {
            if (word.length() > longestWord.length()) {
                longestWord = word;
            }
        }
        for (char ch : line) {
            unsigned char uc = static_cast<unsigned char>(ch);
            if (std::isalpha(uc)) letters++;
            else if (std::isdigit(uc)) digits++;
        }
    }
}

void routeEvenOdd(std::istream& in, std::ostream& outEven, std::ostream& outOdd) {
    int val;
    while (in >> val) {
        if (val % 2 == 0) {
            outEven << val << " ";
        } else {
            outOdd << val << " ";
        }
    }
}

int main() {
    // Line 1: "Modern C++ Streams" -> letters: M,o,d,e,r,n,C,S,t,r,e,a,m,s (14 letters)
    // Line 2: "Word: LongestWordHere" -> letters: W,o,r,d,L,o,n,g,e,s,t,W,o,r,d,H,e,r,e (19 letters)
    // Line 3: "Data 1 2 3" -> letters: D,a,t,a (4 letters), digits: 1,2,3 (3 digits)
    // Total letters: 14 + 19 + 4 = 37, Digits: 3, Lines: 3
    std::string sample = "Modern C++ Streams\nWord: LongestWordHere\nData 1 2 3";
    std::stringstream textStream(sample);

    int lines = 0, letters = 0, digits = 0;
    std::string longest;
    analyzeText(textStream, lines, letters, digits, longest);

    std::cout << "Lines: " << lines << "\n";
    std::cout << "Letters: " << letters << "\n";
    std::cout << "Digits: " << digits << "\n";
    std::cout << "Longest: " << longest << "\n";

    std::stringstream numStream("12 5 7 18 20 33 42 9 81 100");
    std::stringstream evenStream, oddStream;
    routeEvenOdd(numStream, evenStream, oddStream);

    std::cout << "Even numbers: " << evenStream.str() << "\n";
    std::cout << "Odd numbers: " << oddStream.str() << "\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <vector>

void mergeSortedStreams(std::istream& inA, std::istream& inB, std::ostream& out) {
    double a, b;
    bool hasA = static_cast<bool>(inA >> a);
    bool hasB = static_cast<bool>(inB >> b);

    while (hasA && hasB) {
        if (a <= b) {
            out << a << " ";
            hasA = static_cast<bool>(inA >> a);
        } else {
            out << b << " ";
            hasB = static_cast<bool>(inB >> b);
        }
    }
    while (hasA) {
        out << a << " ";
        hasA = static_cast<bool>(inA >> a);
    }
    while (hasB) {
        out << b << " ";
        hasB = static_cast<bool>(inB >> b);
    }
}

void multiplyMatrices(std::istream& inA, std::istream& inB, std::ostream& out) {
    int r1, c1, r2, c2;
    inA >> r1 >> c1;
    std::vector<std::vector<int>> A(r1, std::vector<int>(c1));
    for (int i = 0; i < r1; ++i)
        for (int j = 0; j < c1; ++j)
            inA >> A[i][j];

    inB >> r2 >> c2;
    std::vector<std::vector<int>> B(r2, std::vector<int>(c2));
    for (int i = 0; i < r2; ++i)
        for (int j = 0; j < c2; ++j)
            inB >> B[i][j];

    if (c1 != r2) return;

    out << r1 << " " << c2 << "\n";
    for (int i = 0; i < r1; ++i) {
        for (int j = 0; j < c2; ++j) {
            int sum = 0;
            for (int k = 0; k < c1; ++k) {
                sum += A[i][k] * B[k][j];
            }
            out << sum << (j + 1 == c2 ? "" : " ");
        }
        out << "\n";
    }
}

int main() {
    std::stringstream fileA("1.2 3.5 7.8 9.0");
    std::stringstream fileB("2.1 3.5 4.6 8.9 10.5");
    std::cout << "Merged sorted sequence:\n";
    mergeSortedStreams(fileA, fileB, std::cout);
    std::cout << "\n\n";

    std::stringstream matA("2 2\n1 2\n3 4");
    std::stringstream matB("2 2\n2 0\n1 2");
    std::stringstream matC;
    multiplyMatrices(matA, matB, matC);

    std::cout << "Matrix Product (Rows Cols then data):\n";
    std::cout << matC.str();

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <iomanip>

struct Student {
    std::string name;
    std::string dob;
    std::string gender;
    double score;
};

struct Employee {
    std::string name;
    std::string job;
    std::string phone;
    std::string address;
};

const Employee* findEmployeeByPhone(const std::vector<Employee>& emps, const std::string& targetPhone) {
    for (const auto& emp : emps) {
        if (emp.phone == targetPhone) {
            return &emp;
        }
    }
    return nullptr;
}

int main() {
    std::vector<Student> students = {
        {"Nguyen Van A", "2002-01-15", "Nam", 8.5},
        {"Tran Thi B", "2002-05-20", "Nu", 9.0},
        {"Le Van C", "2002-11-02", "Nam", 7.5}
    };

    double totalScore = 0.0;
    for (const auto& s : students) {
        totalScore += s.score;
    }
    double avgScore = totalScore / students.size();

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Student count: " << students.size() << "\n";
    std::cout << "Average GPA: " << avgScore << "\n\n";

    std::vector<Employee> employees = {
        {"Pham Van X", "Engineer", "0912345678", "123 Le Loi"},
        {"Hoang Thi Y", "Doctor", "0987654321", "456 Tran Phu"}
    };

    std::string searchPhone = "0987654321";
    const Employee* found = findEmployeeByPhone(employees, searchPhone);
    if (found) {
        std::cout << "Employee Found:\n";
        std::cout << "- Name: " << found->name << "\n";
        std::cout << "- Job: " << found->job << "\n";
        std::cout << "- Phone: " << found->phone << "\n";
        std::cout << "- Address: " << found->address << "\n";
    } else {
        std::cout << "Employee with phone " << searchPhone << " not found.\n";
    }

    return 0;
}
